// GENERATED by scripts/build-workflow.js from src/nodes/prepare.js and lib/{caption,config,errors,http,pipeline,results,schedule,video}.js
// Edit those files and run "npm run build" instead of editing here.
const __defs = {
  "caption": function (module, exports, require) {
'use strict';
// Caption / hashtag / title building per platform.
// Limits (from the official docs, Nov 2026):
//   Instagram caption: max 2200 characters, 30 hashtags, 20 @ tags (IG User Media reference)
//   TikTok title:      max 2200 UTF-16 code units (Direct Post reference)
//   YouTube title:     max 100 characters, no < or > (videos resource)
//   YouTube description: max 5000 bytes, no < or > (videos resource)
//   Facebook Reels description: no limit stated in the Reels Publishing doc.

const LIMITS = {
  instagram: { chars: 2200, hashtags: 30, mentions: 20 },
  tiktok: { utf16: 2200 },
  youtube: { titleChars: 100, descriptionBytes: 5000 },
};

const HASHTAG_RE = /#[\p{L}\p{N}_]+/gu;
const MENTION_RE = /(^|[^\p{L}\p{N}_])@[\p{L}\p{N}_.]+/gu;

/** "#a #b", "a, b", "a b", "#a,#b" -> ["#a", "#b"] (deduplicated, order kept). */
function normalizeHashtags(input) {
  if (!input) return [];
  const parts = String(input)
    .split(/[\s,،]+/)
    .map((t) => t.trim())
    .filter(Boolean)
    .map((t) => '#' + t.replace(/^#+/, ''))
    .filter((t) => t.length > 1);
  const seen = new Set();
  const out = [];
  for (const t of parts) {
    const k = t.toLowerCase();
    if (!seen.has(k)) {
      seen.add(k);
      out.push(t);
    }
  }
  return out;
}

/** Caption + hashtags not already present in the caption. */
function combine(caption, hashtags, extra) {
  const text = String(caption || '').replace(/\r\n?/g, '\n').trim();
  const present = new Set((text.match(HASHTAG_RE) || []).map((h) => h.toLowerCase()));
  const tags = normalizeHashtags(hashtags).concat(extra || []).filter((t) => {
    const k = t.toLowerCase();
    if (present.has(k)) return false;
    present.add(k);
    return true;
  });
  if (!tags.length) return text;
  return text ? text + '\n\n' + tags.join(' ') : tags.join(' ');
}

function countHashtags(text) {
  return (String(text).match(HASHTAG_RE) || []).length;
}
function countMentions(text) {
  return (String(text).match(MENTION_RE) || []).length;
}
function charCount(text) {
  return Array.from(String(text)).length; // code points
}

/** Cut to max code points without splitting emoji/surrogates; prefer a word boundary. */
function truncateChars(text, max, ellipsis) {
  const chars = Array.from(String(text));
  if (chars.length <= max) return chars.join('');
  const ell = ellipsis === undefined ? '…' : ellipsis;
  let cut = chars.slice(0, max - ell.length).join('');
  const lastSpace = cut.lastIndexOf(' ');
  if (lastSpace > max * 0.6) cut = cut.slice(0, lastSpace);
  return cut.trimEnd() + ell;
}

function truncateBytes(text, maxBytes) {
  let out = '';
  let bytes = 0;
  for (const ch of Array.from(String(text))) {
    const b = Buffer.byteLength(ch, 'utf8');
    if (bytes + b > maxBytes) break;
    out += ch;
    bytes += b;
  }
  return out;
}

function stripAngle(text) {
  return String(text).replace(/</g, '‹').replace(/>/g, '›');
}

/** YouTube title: explicit title, else the caption's first non-empty line; max 100 chars. */
function buildYoutubeTitle(title, caption) {
  let t = String(title || '').trim();
  if (!t) {
    const first = String(caption || '')
      .split(/\r?\n/)
      .map((l) => l.trim())
      .find(Boolean);
    t = first || 'Short';
  }
  t = stripAngle(t.replace(/\s+/g, ' '));
  return truncateChars(t, LIMITS.youtube.titleChars);
}

function buildYoutubeDescription(caption, hashtags) {
  const hasShorts = /#shorts\b/i.test(String(caption || '')) || normalizeHashtags(hashtags).some((t) => t.toLowerCase() === '#shorts');
  const text = stripAngle(combine(caption, hashtags, hasShorts ? [] : ['#Shorts']));
  if (Buffer.byteLength(text, 'utf8') <= LIMITS.youtube.descriptionBytes) return text;
  // Keep the hashtags line (which carries #Shorts) and shorten the caption part.
  const tagsLine = text.slice(text.lastIndexOf('\n') + 1);
  const room = LIMITS.youtube.descriptionBytes - Buffer.byteLength('…\n\n' + tagsLine, 'utf8');
  return truncateBytes(stripAngle(String(caption || '').trim()), room) + '…\n\n' + tagsLine;
}

/**
 * Build the text for every platform and report problems.
 * returns { facebook:{text}, instagram:{text,errors}, tiktok:{text,errors}, youtube:{title,description,errors} }
 */
function buildCaptions({ caption, hashtags, title }) {
  const full = combine(caption, hashtags);
  const out = {};

  out.facebook = { text: full, errors: [] };

  const igErr = [];
  if (charCount(full) > LIMITS.instagram.chars)
    igErr.push('الكابشن ' + charCount(full) + ' حرف وإنستجرام أقصاه ' + LIMITS.instagram.chars + ' حرف. قصّره.');
  if (countHashtags(full) > LIMITS.instagram.hashtags)
    igErr.push('فيه ' + countHashtags(full) + ' هاشتاج وإنستجرام أقصاه ' + LIMITS.instagram.hashtags + '.');
  if (countMentions(full) > LIMITS.instagram.mentions)
    igErr.push('فيه ' + countMentions(full) + ' منشن (@) وإنستجرام أقصاه ' + LIMITS.instagram.mentions + '.');
  out.instagram = { text: full, errors: igErr };

  const ttErr = [];
  if (full.length > LIMITS.tiktok.utf16) ttErr.push('الكابشن أطول من ' + LIMITS.tiktok.utf16 + ' حرف (حد تيك توك). قصّره.');
  out.tiktok = { text: full, errors: ttErr };

  const ytTitle = buildYoutubeTitle(title, caption);
  out.youtube = { title: ytTitle, description: buildYoutubeDescription(caption, hashtags), errors: [] };
  if (String(title || '').trim() && charCount(String(title).trim()) > LIMITS.youtube.titleChars) {
    out.youtube.warnings = ['عنوان يوتيوب أطول من 100 حرف، فاتقص لـ: "' + ytTitle + '"'];
  }

  if (!String(caption || '').trim()) {
    for (const k of ['facebook', 'instagram', 'tiktok', 'youtube']) out[k].errors.push('الكابشن فاضي.');
  }
  return out;
}

module.exports = {
  LIMITS,
  normalizeHashtags,
  combine,
  countHashtags,
  countMentions,
  charCount,
  truncateChars,
  truncateBytes,
  buildYoutubeTitle,
  buildYoutubeDescription,
  buildCaptions,
};

  },
  "config": function (module, exports, require) {
'use strict';
// Parses and validates accounts.json. Returns Arabic error messages so they
// can be shown on the form directly.

const DEFAULT_SETTINGS = {
  graphApiVersion: 'v27.0',
  keepCloudCopy: false,
  pollTimeoutMinutes: 10,
  igShareToFeed: true,
};

const TIKTOK_PRIVACY = ['PUBLIC_TO_EVERYONE', 'MUTUAL_FOLLOW_FRIENDS', 'FOLLOWER_OF_CREATOR', 'SELF_ONLY'];
const YOUTUBE_PRIVACY = ['public', 'unlisted', 'private'];
const ENV_NAME = /^[A-Z][A-Z0-9_]*$/;

function parseConfig(input) {
  const errors = [];
  let raw = input;
  if (typeof input === 'string') {
    try {
      raw = JSON.parse(input.replace(/^﻿/, '')); // Notepad on Windows may add a BOM
    } catch (e) {
      return { ok: false, errors: ['ملف accounts.json فيه غلطة في الكتابة (JSON مش سليم): ' + e.message], config: null };
    }
  }
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return { ok: false, errors: ['ملف accounts.json لازم يكون object {…}.'], config: null };
  }

  const s = Object.assign({}, DEFAULT_SETTINGS, raw.settings || {});
  if (!/^v\d+\.\d+$/.test(String(s.graphApiVersion))) errors.push('settings.graphApiVersion لازم يكون زي "v27.0".');
  s.keepCloudCopy = s.keepCloudCopy === true;
  s.pollTimeoutMinutes = Number(s.pollTimeoutMinutes) > 0 ? Number(s.pollTimeoutMinutes) : 10;
  s.igShareToFeed = s.igShareToFeed !== false;

  const destinations = [];
  const labels = new Set();
  const addDest = (d) => {
    if (labels.has(d.label)) {
      errors.push('فيه اسمين متكررين: "' + d.label + '". غيّر الاسم في accounts.json.');
      return;
    }
    labels.add(d.label);
    destinations.push(d);
  };

  const pages = raw.facebookPages || [];
  if (!Array.isArray(pages)) errors.push('facebookPages لازم تكون قائمة [ ].');
  else
    pages.forEach((p, i) => {
      const where = 'facebookPages[' + i + ']';
      if (!p || p.enabled === false) return;
      if (!p.name) errors.push(where + ': ناقص "name".');
      if (!/^\d+$/.test(String(p.pageId || ''))) errors.push(where + ': "pageId" لازم يكون أرقام بس.');
      if (!ENV_NAME.test(String(p.tokenEnv || ''))) errors.push(where + ': "tokenEnv" لازم يكون اسم متغير في .env زي FB_TOKEN_PAGE_1.');
      if (p.name && p.pageId && p.tokenEnv)
        addDest({ platform: 'facebook', key: 'fb:' + p.pageId, label: 'فيسبوك — ' + p.name, name: p.name, pageId: String(p.pageId), tokenEnv: p.tokenEnv });
    });

  const igs = raw.instagramAccounts || [];
  if (!Array.isArray(igs)) errors.push('instagramAccounts لازم تكون قائمة [ ].');
  else
    igs.forEach((a, i) => {
      const where = 'instagramAccounts[' + i + ']';
      if (!a || a.enabled === false) return;
      if (!a.name) errors.push(where + ': ناقص "name".');
      if (!/^\d+$/.test(String(a.igUserId || ''))) errors.push(where + ': "igUserId" لازم يكون أرقام بس (ده instagram_business_account id).');
      if (!ENV_NAME.test(String(a.tokenEnv || ''))) errors.push(where + ': "tokenEnv" لازم يكون اسم متغير في .env (توكن الصفحة المربوطة بالحساب).');
      if (a.name && a.igUserId && a.tokenEnv)
        addDest({ platform: 'instagram', key: 'ig:' + a.igUserId, label: 'إنستجرام — ' + a.name, name: a.name, igUserId: String(a.igUserId), tokenEnv: a.tokenEnv });
    });

  const tt = raw.tiktok || {};
  if (tt.enabled === true) {
    const privacy = tt.privacyLevel || 'SELF_ONLY';
    if (!TIKTOK_PRIVACY.includes(privacy)) errors.push('tiktok.privacyLevel لازم يكون واحد من: ' + TIKTOK_PRIVACY.join(', '));
    addDest({
      platform: 'tiktok',
      key: 'tiktok',
      label: 'تيك توك' + (tt.name ? ' — ' + tt.name : ''),
      name: tt.name || 'TikTok',
      privacyLevel: privacy,
      disableComment: tt.disableComment === true,
      disableDuet: tt.disableDuet === true,
      disableStitch: tt.disableStitch === true,
      isAigc: tt.isAigc === true,
    });
  }

  const yt = raw.youtube || {};
  if (yt.enabled === true) {
    const privacy = yt.privacyStatus || 'public';
    if (!YOUTUBE_PRIVACY.includes(privacy)) errors.push('youtube.privacyStatus لازم يكون public أو unlisted أو private.');
    addDest({
      platform: 'youtube',
      key: 'youtube',
      label: 'يوتيوب شورتس' + (yt.name ? ' — ' + yt.name : ''),
      name: yt.name || 'YouTube Shorts',
      privacyStatus: privacy,
      categoryId: String(yt.categoryId || '22'),
      madeForKids: yt.madeForKids === true,
      containsSyntheticMedia: yt.containsSyntheticMedia === true,
    });
  }

  if (!destinations.length && !errors.length) {
    errors.push('مفيش ولا صفحة أو حساب مفعّل في accounts.json. ضيف صفحة فيسبوك أو فعّل tiktok/youtube.');
  }

  return { ok: errors.length === 0, errors, config: { settings: s, destinations } };
}

/** Map the checkbox labels the form returns back to destination objects. */
function selectDestinations(config, selectedLabels) {
  const list = Array.isArray(selectedLabels) ? selectedLabels : selectedLabels ? [selectedLabels] : [];
  const set = new Set(list.map(String));
  return config.destinations.filter((d) => set.has(d.label));
}

module.exports = { parseConfig, selectDestinations, DEFAULT_SETTINGS, TIKTOK_PRIVACY, YOUTUBE_PRIVACY };

  },
  "errors": function (module, exports, require) {
'use strict';
// Turns API / network errors into plain Egyptian-Arabic reasons + what to do.
// Codes listed here come from the official docs (Meta Graph API error codes,
// Reels Publishing API error table, TikTok Content Posting error tables,
// YouTube Data API errors, Cloudinary upload API). Anything unknown falls
// back to the platform's own message so nothing is hidden.

class PublishError extends Error {
  /** code: our internal code, ar: Arabic reason, fix: what to do */
  constructor(code, ar, fix, details) {
    super(ar);
    this.name = 'PublishError';
    this.code = code;
    this.ar = ar;
    this.fix = fix || '';
    this.details = details;
  }
}

const README = 'README.md';

function metaError(body) {
  const e = (body && body.error) || {};
  return { code: Number(e.code), subcode: Number(e.error_subcode), message: e.error_user_msg || e.message || '', type: e.type };
}

function mapMeta(err, platformAr, tokenEnv) {
  const m = metaError(err.body);
  const tok = tokenEnv ? ' (المتغير ' + tokenEnv + ' في ملف .env)' : '';
  if (m.code === 190 || err.status === 401)
    return ['التوكن خلص أو اتلغى' + tok + '.', 'جدّده من Graph API Explorer بالخطوات اللي في ' + README + ' (جزء Meta: "توكن الصفحة")، حطه في .env وشغّل stop.bat ثم start.bat.'];
  if (m.code === 10 || (m.code >= 200 && m.code <= 299))
    return ['التطبيق ناقصه صلاحية على ' + platformAr + ': ' + m.message, 'اعمل توكن جديد وانت مختار الصلاحيات كلها اللي في ' + README + ' (pages_manage_posts, instagram_content_publish …).'];
  if ([4, 17, 32, 613].includes(m.code))
    return ['وصلت لحد عدد الطلبات المسموح من ميتا.', 'استنى ساعة وجرب تاني.'];
  if (m.code === 368) return ['ميتا قافلة النشر مؤقتًا على الحساب ده (حماية من السبام).', 'افتح الصفحة من فيسبوك وشوف التنبيهات، واستنى قبل ما تجرب تاني.'];
  if (m.code === 1363040) return ['أبعاد الفيديو مش مقبولة في فيسبوك (لازم بين 16:9 و 9:16).', 'صدّر الفيديو 1080x1920.'];
  if (m.code === 1363127) return ['جودة الفيديو قليلة (أقل حاجة 540x960).', 'صدّر الفيديو 1080x1920.'];
  if (m.code === 1363128) return ['مدة الفيديو مش مقبولة (ريلز فيسبوك من 3 لـ 90 ثانية).', 'قصّر الفيديو لـ 90 ثانية أو أقل.'];
  if (m.code === 1363129) return ['عدد الفريمات مش مقبول (من 24 لـ 60).', 'صدّر الفيديو 30 fps.'];
  if (m.code === 100) return ['ميتا رفضت الطلب: ' + m.message, 'اتأكد إن الـ ID في accounts.json صح وإن التوكن بتاع نفس الصفحة.'];
  if (m.message) return ['ميتا رجّعت خطأ: ' + m.message + (m.code ? ' (كود ' + m.code + ')' : ''), 'لو المشكلة اتكررت دوّر على الكود في صفحة Graph API Error Codes.'];
  return null;
}

const TIKTOK = {
  access_token_invalid: ['ربط تيك توك خلص.', 'افتح فورم "ربط تيك توك" واربط الحساب تاني.'],
  scope_not_authorized: ['تيك توك مش مدّي التطبيق صلاحية video.publish.', 'فعّل Direct Post و video.publish في التطبيق، واربط الحساب تاني من فورم "ربط تيك توك".'],
  spam_risk_too_many_posts: ['وصلت لحد النشر اليومي في تيك توك.', 'جرب بكرة.'],
  spam_risk_user_banned_from_posting: ['تيك توك مانع الحساب من النشر.', 'افتح التطبيق وشوف التنبيهات.'],
  reached_active_user_cap: ['التطبيق وصل لحد المستخدمين اليومي (التطبيق غير المراجَع حده 5 حسابات).', 'جرب بكرة.'],
  unaudited_client_can_only_post_to_private_accounts: ['التطبيق لسه ماعداش مراجعة تيك توك، فبينشر بس على حسابات Private.', 'حوّل حساب تيك توك لـ Private من الإعدادات وجرب تاني (شوف ' + README + ').'],
  privacy_level_option_mismatch: ['مستوى الخصوصية في accounts.json مش متاح لحسابك.', 'خلّي tiktok.privacyLevel = "SELF_ONLY".'],
  url_ownership_unverified: ['تيك توك طالب توثيق الدومين.', 'إحنا بنرفع الملف مباشرة؛ لو ظهر الخطأ ده بلّغ عنه.'],
  rate_limit_exceeded: ['طلبات كتير ورا بعض لتيك توك.', 'استنى دقيقة وجرب تاني.'],
  invalid_param: ['تيك توك رفض الطلب.', 'شوف تفاصيل الخطأ في ملف اللوج.'],
  file_format_check_failed: ['تيك توك رفض نوع الملف.', 'صدّر الفيديو MP4 (H.264).'],
  duration_check_failed: ['مدة الفيديو مش مقبولة في تيك توك.', 'قصّر الفيديو.'],
  frame_rate_check_failed: ['عدد الفريمات مش مقبول في تيك توك (23–60).', 'صدّر الفيديو 30 fps.'],
  picture_size_check_failed: ['أبعاد الفيديو مش مقبولة في تيك توك (360–4096 بكسل).', 'صدّر الفيديو 1080x1920.'],
  internal: ['تيك توك عنده مشكلة مؤقتة.', 'جرب تاني بعد شوية.'],
};

function mapTikTok(err) {
  const body = err.body || {};
  const code = (body.error && body.error.code) || body.error || err.tiktokCode;
  if (code && TIKTOK[code]) return TIKTOK[code];
  if (err.status === 401) return TIKTOK.access_token_invalid;
  if (code === 'invalid_grant') return ['ربط تيك توك خلص (الـ refresh token انتهى أو اتغير).', 'افتح فورم "ربط تيك توك" واربط الحساب تاني.'];
  const msg = (body.error && body.error.message) || body.error_description || body.message;
  if (msg) return ['تيك توك رجّع خطأ: ' + msg + (code ? ' (' + code + ')' : ''), 'شوف تفاصيل الخطأ في ملف اللوج.'];
  return null;
}

function mapYouTube(err) {
  const body = err.body || {};
  const e = body.error || {};
  const reason = (e.errors && e.errors[0] && e.errors[0].reason) || e.status || '';
  if (err.nodeError && /credential/i.test(e.message || ''))
    return ['n8n مش لاقي حساب يوتيوب (YouTube credential).', 'افتح الـ workflow في n8n، وفي نودين "يوتيوب: بدء الرفع" و "يوتيوب: رفع الفيديو" اختار YouTube account، واعمل Publish.'];
  if (err.nodeError) return ['n8n ماقدرش يكلم يوتيوب: ' + e.message, 'افتح n8n ← Executions وشوف التفاصيل.'];
  if (err.status === 401 || reason === 'authError' || reason === 'UNAUTHENTICATED')
    return ['ربط يوتيوب في n8n خلص (التوكن مش صالح).', 'افتح n8n ← Credentials ← YouTube account ← Reconnect. لو التطبيق في وضع Testing بيخلص كل 7 أيام (شوف ' + README + ').'];
  if (reason === 'quotaExceeded' || reason === 'uploadLimitExceeded' || reason === 'rateLimitExceeded')
    return ['خلصت حصة يوتيوب اليومية للرفع.', 'الحصة بتتجدد 12 بالليل بتوقيت كاليفورنيا (حوالي 10 الصبح بتوقيت مصر). جرب بعدها.'];
  if (reason === 'invalidTitle') return ['يوتيوب رفض العنوان.', 'اكتب عنوان أقل من 100 حرف ومن غير < أو >.'];
  if (reason === 'invalidDescription') return ['يوتيوب رفض الوصف.', 'قصّر الكابشن وشيل < و >.'];
  if (reason === 'forbidden' || err.status === 403)
    return ['يوتيوب رافض الرفع: ' + (e.message || reason), 'اتأكد إن YouTube Data API v3 متفعّل وإن حسابك عنده قناة.'];
  if (e.message) return ['يوتيوب رجّع خطأ: ' + e.message, 'شوف تفاصيل الخطأ في ملف اللوج.'];
  return null;
}

function mapCloudinary(err) {
  const msg = (err.body && err.body.error && err.body.error.message) || '';
  if (err.status === 401 || /signature|api_key|api key/i.test(msg))
    return ['بيانات Cloudinary غلط (' + msg + ').', 'راجع CLOUDINARY_CLOUD_NAME و CLOUDINARY_API_KEY و CLOUDINARY_API_SECRET في .env.'];
  if (/too large|size/i.test(msg) || err.status === 413)
    return ['الفيديو أكبر من الحد المسموح في خطة Cloudinary المجانية (' + msg + ').', 'قلّل حجم الفيديو أو شوف الحد في Cloudinary Console ← Settings.'];
  if (msg) return ['Cloudinary رجّع خطأ: ' + msg, 'إنستجرام محتاج Cloudinary يشتغل عشان ياخد الفيديو.'];
  return null;
}

/** Map any error to {ar, fix, code, raw}. */
function mapError(platform, err, ctx) {
  ctx = ctx || {};
  if (err instanceof PublishError || (err && err.name === 'PublishError')) return { ar: err.ar, fix: err.fix, code: err.code, raw: err.details };
  let pair = null;
  if (err && ['ENOTFOUND', 'EAI_AGAIN', 'ECONNREFUSED', 'ECONNRESET', 'ETIMEDOUT', 'NETWORK'].includes(err.code)) {
    pair = err.code === 'ETIMEDOUT'
      ? ['الطلب أخد وقت طويل ومفيش رد.', 'اتأكد إن النت شغال وجرب تاني.']
