function normalizeHashtags(input) {
  if (!input) return [];
  const parts = String(input)
    .split(/[\s,،]+/)
    .map((t) => t.trim())
    .filter(Boolean)
    .map((t) => '#' + t.replace(/^#+/, ''))
    .filter((t) => t.length > 1);
  const seen = new Set();
  const out = [];
  for (const t of parts) {
    const k = t.toLowerCase();
    if (!seen.has(k)) {
      seen.add(k);
      out.push(t);
    }
  }
  return out;
