// Parse the optional "publish at" date/time from the form (Cairo time, DST aware).

const TZ = 'Africa/Cairo';

function toLatinDigits(s) {
  return String(s || '')
    .replace(/[٠-٩]/g, (d) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
