    .filter((k) => obj[k] !== undefined && obj[k] !== null)
    .map((k) => {
      const v = typeof obj[k] === 'object' ? JSON.stringify(obj[k]) : String(obj[k]);
      return encodeURIComponent(k) + '=' + encodeURIComponent(v);
