      req.destroy(new HttpError('Request timed out', { code: 'ETIMEDOUT', url: redact(url) }));
    });
    req.on('error', (e) => {
      if (e instanceof HttpError) return reject(e);
      reject(new HttpError(e.message, { code: e.code || 'NETWORK', url: redact(url) }));
    });
